import random
random.seed(0)

def pretrained_weights():
    # already covered as a pretrained model already knowing general patterns in this topic
    return {"w1": 0.8, "w2": -0.3, "w3": 0.5, "w4": 0.1}

def full_fine_tune_step(weights, gradients, learning_rate):
    # already covered as updating every single weight in this topic
    updated = {}
    for key in weights:
        updated[key] = weights[key] - learning_rate * gradients[key]
    return updated

weights = pretrained_weights()
print(f"Pretrained weights (already covered in this topic): {weights}")

# already covered as smaller task specific dataset producing gradients in this topic
gradients = {"w1": 0.05, "w2": -0.02, "w3": 0.03, "w4": -0.01}
learning_rate = 0.01  # already covered as lower learning rates for fine-tuning in this topic

for step in range(3):
    weights = full_fine_tune_step(weights, gradients, learning_rate)
    print(f"After fine-tuning step {step + 1} (already covered as updating every weight in this topic): {weights}")
